#region Using

using System;
using System.Data;
using System.Collections;
using DCore;

#endregion

namespace TransportObject
{
    /// <summary>
	/// Lịch trình phương tiện
	/// </summary>	
    public partial class TPT_VehicleSchedule
	{	

		#region Methods	

        public bool AddOrEdit()
        {
            if (!bolIsExistIData)
                objIData = DCore.Data.CreateData();
            try
            {
                objIData.CreateNewStoredProcedure("TPT_VehicleSchedule_AddOrEdit");
                objIData.AddParameter(P_VehicleScheduleID, this.lngVehicleScheduleID);
                objIData.AddParameter(P_VehicleID, this.intVehicleID);
                objIData.AddParameter(P_WorkDate, this.dtmWorkDate);
                objIData.AddParameter(P_FromTime, this.dtmFromTime);
                objIData.AddParameter(P_ToTime, this.dtmToTime);
                objIData.AddParameter(P_WorkHours, this.decWorkHours);
                objIData.AddParameter(P_PlaceID, this.intPlaceID);
                objIData.AddParameter(P_PlaceDetail, this.strPlaceDetail);
                objIData.AddParameter(P_DriverID, this.lngDriverID);
                objIData.AddParameter(P_DriverName, this.strDriverName);
                objIData.AddParameter(P_DriverTel, this.strDriverTel);
                objIData.AddParameter(P_ActualDriverID, this.lngActualDriverID);
                objIData.AddParameter(P_ActualDriverName, this.strActualDriverName);
                objIData.AddParameter(P_ActualDriverTel, this.strActualDriverTel);
                objIData.AddParameter(P_HelperName, this.strHelperName);
                objIData.AddParameter(P_WorkContent, this.strWorkContent);
                objIData.AddParameter(P_Description, this.strDescription);
                objIData.AddParameter(P_IsCanceled, this.bolIsCanceled);
                objIData.AddParameter(P_UpdatedUser, this.strUpdatedUser);
                this.lngVehicleScheduleID = Convert.ToInt64(objIData.ExecStoreToString());
                return true;
            }
            catch (Exception objEx)
            {
                if (bolIsExistIData)
                    this.RollBackTransaction();
                new SystemError(SystemConfig.ConnectionString, "Loi cap nhat TPT_VehicleSchedule_AddOrEdit", objEx);
                this.objErrorException = objEx;
                return false;
            }
            finally
            {
                if (!bolIsExistIData)
                    objIData.Disconnect();
            }
        }


		#endregion

	}
}

using System;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Threading;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using Libs;
using Global;
using TransportObject;
using GeneralService;
using GeneralObject;

namespace Transport.Schedule
{
    /// <summary>
    /// Lập lịch phương tiện - nhập trực tiếp trên lưới
    /// </summary>
    public partial class frmVehicleSchedule : FormBase, IForm
    {
        #region Consts

        public const string PERMISSION_ADD = "TPT_VehicleSchedule_Add";
        public const string PERMISSION_DELETE = "TPT_VehicleSchedule_Delete";
        public const string PERMISSION_EDIT = "TPT_VehicleSchedule_Edit";
        public const string PERMISSION_VIEW = "TPT_VehicleSchedule_View";

        #endregion

        #region Variables

        DataTable dtbData = null;
        bool bolIsRefresh = false;
        bool bolIsSingleDay = true;

        #endregion

        #region IForm Members

        private static frmVehicleSchedule _instance = null;

        public static frmVehicleSchedule Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmVehicleSchedule();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmVehicleSchedule()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            gvData.OptionsBehavior.Editable = UserSession.HasPermission(PERMISSION_EDIT);
            gvData.OptionsView.NewItemRowPosition = (!bolIsSingleDay && UserSession.HasPermission(PERMISSION_ADD))
                ? DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.Top
                : DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.None;
        }

        private void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                GEN_PlaceService.InitLookUpEdit(lookupPlace);
            }
        }

        private int? GetSearchPlaceID()
        {
            if (lookupPlace.EditValue == null || lookupPlace.EditValue == DBNull.Value)
                return null;

            int intPlaceID;
            if (int.TryParse(lookupPlace.EditValue.ToString(), out intPlaceID))
            {
                if (intPlaceID <= 0)
                    return null;
                return intPlaceID;
            }
            return null;
        }

        private void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                TPT_VehicleSchedule obj = new TPT_VehicleSchedule();
                dtbData = obj.GetDataTable("TPT_VehicleSchedule_SEARCH",
                    "@FromDate", dtmFrom.EditValueDate,
                    "@ToDate", dtmTo.EditValueDate,
                    "@PlaceID", GetSearchPlaceID());

                if (dtbData != null)
                {
                    if (dtbData.Rows.Count > 0 && dtbData.Columns.Contains("IsSingleDay"))
                        bolIsSingleDay = Convert.ToBoolean(dtbData.Rows[0]["IsSingleDay"]);
                    else
                        bolIsSingleDay = dtmFrom.EditValueDate.Date == dtmTo.EditValueDate.Date;

                    CheckPermission();
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "TPT_VehicleSchedule_SEARCH", bolIsRefresh);
                    gcData.DataSource = dtbData;
                    ModifyGrid();
                    bolIsRefresh = false;
                    btnSave.Enabled = mnuItemSave.Enabled = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        private void ModifyGrid()
        {
            if (gvData.Columns["PlaceID"] != null && (gvData.Columns["PlaceID"].ColumnEdit == null || bolIsRefresh))
                GEN_PlaceService.InitRepositoryLookUpEdit(gvData, "PlaceID");

            if (!bolIsSingleDay && gvData.Columns["VehicleID"] != null && (gvData.Columns["VehicleID"].ColumnEdit == null || bolIsRefresh))
                TransportService.TPT_VehicleService.InitRepositoryLookUpEdit(gvData, "VehicleID");

            if (gvData.Columns["WorkDate"] != null)
            {
                gvData.Columns["WorkDate"].Visible = !bolIsSingleDay;
                gvData.Columns["WorkDate"].OptionsColumn.AllowEdit = !bolIsSingleDay;
            }

            if (gvData.Columns["VehicleCode"] != null)
                gvData.Columns["VehicleCode"].OptionsColumn.AllowEdit = false;
            if (gvData.Columns["VehicleCode2"] != null)
                gvData.Columns["VehicleCode2"].OptionsColumn.AllowEdit = false;
            if (gvData.Columns["VehicleName"] != null)
                gvData.Columns["VehicleName"].OptionsColumn.AllowEdit = false;
            if (gvData.Columns["DriverName"] != null)
                gvData.Columns["DriverName"].OptionsColumn.AllowEdit = false;

            if (gvData.Columns["VehicleID"] != null)
            {
                gvData.Columns["VehicleID"].Visible = !bolIsSingleDay;
                gvData.Columns["VehicleID"].OptionsColumn.AllowEdit = !bolIsSingleDay;
            }
        }

        private bool SaveData()
        {
            if (dtbData == null)
                return true;

            TPT_VehicleSchedule item0 = new TPT_VehicleSchedule();
            item0.BeginTransaction();

            foreach (DataRow drw in dtbData.Rows)
            {
                if (drw.RowState == DataRowState.Deleted)
                    continue;

                if (drw.RowState != DataRowState.Modified && drw.RowState != DataRowState.Added)
                    continue;

                TPT_VehicleSchedule item = new TPT_VehicleSchedule();
                item.IDB = item0.IDB;
                if (!item.Parse(drw))
                    continue;

                if (bolIsSingleDay && (item.WorkDate == null || item.WorkDate == DateTime.MinValue))
                    item.WorkDate = dtmFrom.EditValueDate;

                item.UpdatedUser = UserSession.Username;
                if (!item.AddOrEdit())
                {
                    ErrorManager.Error("Việc lưu lịch trình bị lỗi!\r\n" + item.ErrorException.Message);
                    return false;
                }

                if (item.VehicleScheduleID != null && item.VehicleScheduleID > 0)
                    drw[TPT_VehicleSchedule.C_VehicleScheduleID] = item.VehicleScheduleID;
            }

            item0.CommitTransaction();
            return true;
        }

        private bool DeleteData()
        {
            TPT_VehicleSchedule objItem = new TPT_VehicleSchedule();
            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = arrRowIndex.Length - 1; i >= 0; i--)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw == null)
                    continue;

                long lngVehicleScheduleID = 0;
                if (drw[TPT_VehicleSchedule.C_VehicleScheduleID] != DBNull.Value)
                    lngVehicleScheduleID = Convert.ToInt64(drw[TPT_VehicleSchedule.C_VehicleScheduleID]);

                if (lngVehicleScheduleID > 0)
                {
                    if (!objItem.Delete(lngVehicleScheduleID, UserSession.Username))
                    {
                        ErrorManager.Error("Không xóa được lịch trình đã lưu!");
                        return false;
                    }
                }

                gvData.DeleteRow(arrRowIndex[i]);
            }
            return true;
        }

        private string CheckValidate(DataRow drw)
        {
            if (drw == null)
                return "";

            TPT_VehicleSchedule item = new TPT_VehicleSchedule();
            if (!item.Parse(drw))
                return "Dữ liệu dòng không hợp lệ!";

            if (item.VehicleID == null || item.VehicleID <= 0)
                return "Bạn phải chọn phương tiện!";

            if (item.WorkDate == null)
                return "Bạn phải nhập ngày làm việc!";

            return "";
        }

        #endregion

        #region Form Actions

        static bool bolIsLoaded = false;

        private void frmVehicleSchedule_Load(object sender, EventArgs e)
        {
            if (!bolIsLoaded)
            {
                DateTime dtm = DateTime.Now.Date;
                dtmFrom.EditValue = dtm;
                dtmTo.EditValue = dtm;
                SetToolTip();
                new Thread(LoadReferenceData).Start();
                bolIsLoaded = true;
            }
            CheckPermission();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (dtmFrom.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày bắt đầu!");
                dtmFrom.Focus();
                return;
            }
            if (dtmTo.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày kết thúc!");
                dtmTo.Focus();
                return;
            }
            if (dtmFrom.EditValueDate > dtmTo.EditValueDate)
            {
                MessageManager.Warning("Từ ngày không được lớn hơn đến ngày!");
                dtmFrom.Focus();
                return;
            }

            new Thread(LoadData).Start();
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                bolIsRefresh = true;
                new Thread(LoadData).Start();
                btnSave.Enabled = mnuItemSave.Enabled = false;
            }
        }

        private void btnDelete_Click(object sender, EventArgs e)
        {
            if (MessageManager.Confirm("Bạn thực sự muốn xóa những dòng lịch trình đã chọn?") == DialogResult.Yes)
            {
                if (DeleteData())
                {
                    btnSave.Enabled = mnuItemSave.Enabled = true;
                }
            }
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            btnSearch_Click(null, null);
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void frmVehicleSchedule_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;
                case Keys.F4:
                    if (btnDelete.Enabled)
                        btnDelete_Click(sender, null);
                    break;
                case Keys.F5:
                    mnuItemRefresh_Click(sender, null);
                    break;
                case Keys.F6:
                    if (mnuItemSave.Enabled)
                        btnSave_Click(sender, null);
                    break;
                case Keys.F8:
                    if (!bolIsSingleDay)
                        gvData.AddNewRow();
                    break;
                case Keys.Escape:
                    btnClose_Click(sender, null);
                    break;
            }
        }

        private void gvData_SelectionChanged(object sender, DevExpress.Data.SelectionChangedEventArgs e)
        {
            mnuItemDelete.Enabled = btnDelete.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_DELETE);
        }

        #endregion

        #region Grid Actions

        private void gvData_ShowingEditor(object sender, CancelEventArgs e)
        {
            if (!UserSession.HasPermission(PERMISSION_EDIT))
            {
                e.Cancel = true;
                return;
            }

            if (bolIsSingleDay && gvData.FocusedColumn != null && gvData.FocusedColumn.FieldName == TPT_VehicleSchedule.C_WorkDate)
                e.Cancel = true;
        }

        private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
        {
            string strError = CheckValidate(gvData.GetFocusedDataRow());
            if (strError != "")
            {
                e.ErrorText = strError;
                e.Valid = false;
            }
            else
                btnSave.Enabled = mnuItemSave.Enabled = true;
        }

        private void gvData_InvalidRowException(object sender, DevExpress.XtraGrid.Views.Base.InvalidRowExceptionEventArgs e)
        {
            e.ExceptionMode = DevExpress.XtraEditors.Controls.ExceptionMode.DisplayError;
        }

        private void gvData_RowCellStyle(object sender, DevExpress.XtraGrid.Views.Grid.RowCellStyleEventArgs e)
        {
            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw == null)
                return;

            if (drw.RowState == DataRowState.Added)
                e.Appearance.BackColor = Color.LightSkyBlue;
            else if (drw.RowState == DataRowState.Modified)
                e.Appearance.BackColor = Color.LightPink;
        }

        private void gvData_InitNewRow(object sender, DevExpress.XtraGrid.Views.Grid.InitNewRowEventArgs e)
        {
            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw == null)
                return;

            drw[TPT_VehicleSchedule.C_VehicleScheduleID] = 0;
            drw[TPT_VehicleSchedule.C_WorkDate] = dtmFrom.EditValueDate;
            drw[TPT_VehicleSchedule.C_IsCanceled] = false;
        }

        #endregion
    }
}

