}

private bool CommitGridEdit()
{
    try
    {
        gvData.CloseEditor();
        gvData.UpdateCurrentRow();
    }
    catch
    {
        return false;
    }
    return true;
}

private bool IsRowNeedSave(DataRow drw)
{
    if (drw == null)
        return false;

    if (drw.RowState == DataRowState.Added || drw.RowState == DataRowState.Modified)
        return true;

    if (dtbData.Columns.Contains(C_IsEdit) && !Convert.IsDBNull(drw[C_IsEdit]))
        return Convert.ToBoolean(drw[C_IsEdit]);

    return false;
}

private void MarkRowEdited(DataRow drw)
{
    if (drw == null)
        return;

    if (dtbData != null && dtbData.Columns.Contains(C_IsEdit))
        drw[C_IsEdit] = true;

