private bool SaveData()
{
    if (dtbData == null)
        return false;

    if (!CommitGridEdit())
    {
        MessageManager.Warning("Dữ liệu dòng hiện tại chưa hợp lệ!");
        return false;
    }

    TPT_VehicleSchedule item0 = new TPT_VehicleSchedule();
    item0.BeginTransaction();

    int intSaveCount = 0;

    foreach (DataRow drw in dtbData.Rows)
    {
        if (drw.RowState == DataRowState.Deleted)
            continue;

        if (!IsRowNeedSave(drw))
            continue;

        if (IsEmptyScheduleRow(drw))
            continue;

        string strError = CheckValidate(drw);
        if (strError != "")
        {
            item0.RollBackTransaction();
            ErrorManager.Error(strError);
            return false;
        }

        TPT_VehicleSchedule item = new TPT_VehicleSchedule();
        item.IDB = item0.IDB;
        if (!item.ParseSearchRow(drw))
        {
            item0.RollBackTransaction();
            ErrorManager.Error("Dữ liệu dòng không hợp lệ!");
            return false;
        }

        if (bolIsSingleDay && (item.WorkDate == null || item.WorkDate == DateTime.MinValue))
            item.WorkDate = dtmFrom.EditValueDate;

        if (item.WorkDate == null || item.WorkDate == DateTime.MinValue)
        {
            item0.RollBackTransaction();
            ErrorManager.Error("Bạn phải nhập ngày làm việc!");
            return false;
        }

        item.FromTime = CombineWorkDateTime(item.WorkDate, item.FromTime);
        item.ToTime = CombineWorkDateTime(item.WorkDate, item.ToTime);

        item.UpdatedUser = UserSession.Username;
        if (!item.AddOrEdit())
        {
            item0.RollBackTransaction();
            ErrorManager.Error("Việc lưu lịch trình bị lỗi!\r\n" + item.ErrorException.Message);
            return false;
        }

        if (item.VehicleScheduleID != null && item.VehicleScheduleID > 0)
            drw[TPT_VehicleSchedule.C_VehicleScheduleID] = item.VehicleScheduleID;

        if (dtbData.Columns.Contains(C_IsEdit))
            drw[C_IsEdit] = false;

        intSaveCount++;
    }

    if (intSaveCount == 0)
    {
        item0.RollBackTransaction();
        MessageManager.Warning("Không có dữ liệu thay đổi cần lưu!");
        return false;
    }

    item0.CommitTransaction();
    dtbData.AcceptChanges();
    return true;
}

